// Probe (coverage agent, 2026-10-16): can a life made at Yale reach bank.savings_notice through its home account?
import { readFileSync } from 'node:fs';
import { createSave, loadPlacesFor, loadSave } from '@/engine';
import { newLifeConfig, withFamily, type NewSaveConfig } from '@/engine/world/bootstrap';
import { addCountryHolidays } from '@/engine/content/holidays';
import { deserialise, serialise } from '@/engine/persistence/adapter';
import { homeAccountRefusal } from '@/engine/systems/homeaccount';
for (const country of ['uk', 'de', 'jp', 'fr']) addCountryHolidays(country, readFileSync(`public/holidays/${country}.tsv`, 'utf8'));
for (const wealth of ['modest', 'comfortable', 'wealthy', 'inherited'] as const) {
  for (const bank of ['de-deutsche-bank', 'de-postbank', 'de-berliner-sparkasse']) {
    const config: NewSaveConfig = { ...withFamily(newLifeConfig(), wealth), homeRegionId: 'de-be-berlin', firstName: 'Ada', lastName: 'Cole', pronouns: 'she/her', bankId: 'us-chase', priorResidence: { cityId: 'de-be-berlin', fromYear: 2002, fromMonth: 6 }, homeBankId: bank };
    const why = homeAccountRefusal(config, bank);
    if (why) { console.log(wealth, bank, 'REFUSED:', why); continue; }
    const sim = createSave(1, 'cov-sn', config);
    await loadPlacesFor(sim.universe);
    const mine = Object.values(sim.universe.accounts).filter((a) => !a.nominal && a.ownerId === sim.player.id && !a.closedAt);
    const savings = mine.find((a) => a.bankId === bank && a.kind === 'savings');
    console.log(wealth, bank, 'accounts:', mine.map((a) => `${a.name}@${a.bankId}:${a.balance}${a.held !== undefined ? `(held ${a.held})` : ''}`).join(', '));
    if (!savings) continue;
    const r = sim.execute<{ closed: string; on?: number }>({ kind: 'bank.close_savings', payload: { accountId: savings.id } });
    console.log('  close_savings:', r.ok ? JSON.stringify(r.value) : r.error, r.ok && r.value?.on ? new Date(r.value.on).toISOString() : '');
    if (r.ok && r.value?.on) {
      const reloaded = loadSave(deserialise(serialise(sim.universe)) as never);
      reloaded.advanceTo(r.value.on + 3_600_000);
      const s2 = reloaded.universe.accounts[savings.id]!;
      const notes = reloaded.universe.notifications?.filter?.((n: { title: string }) => /Closed/.test(n.title)).map((n: { title: string; body: string }) => `${n.title}: ${n.body}`) ?? [];
      console.log('  after notice: closedAt', s2.closedAt ? new Date(s2.closedAt).toISOString() : 'open', 'balance', s2.balance, '|', notes.slice(-2).join(' || '));
    }
  }
}

// Probe (coverage agent, 2026-10-16): is Arrange It drawn for an account kept at home, where the command refuses?
import { readFileSync } from 'node:fs';
import { expect, it, vi } from 'vitest';
import { createElement } from 'react';
import { renderToStaticMarkup } from 'react-dom/server';
import { createSave, loadPlacesFor } from '@/engine';
import type { Simulation } from '@/engine/core/simulation';
import { instantFromZoned } from '@/engine/core/time';
import { newLifeFrom, type NewSaveConfig } from '@/engine/world/bootstrap';
import { addCountryHolidays } from '@/engine/content/holidays';
import { bankById } from '@/engine/content/banks';

const h = vi.hoisted(() => ({ sim: undefined as unknown as import('@/engine/core/simulation').Simulation, clicks: [] as { feature: string; label: string; onClick?: () => void }[], toasts: [] as string[] }));
vi.mock('@/ui/kept', async (orig) => { const real = await orig<typeof import('@/ui/kept')>(); return { ...real, useKept: <T,>(_key: string, initial: T) => [initial, () => undefined] as const }; });
vi.mock('@/app/game-context', () => {
  const noop = () => undefined;
  const game = () => new Proxy({ get sim() { return h.sim; }, version: 0, run: (kind: string, payload: Record<string, unknown> = {}) => h.sim.execute({ kind, payload }), toast: (m: string) => { h.toasts.push(m); }, navigate: noop, standingAt: null } as Record<string, unknown>, { get: (t, k) => (k in t ? t[k as string] : noop) });
  return { useGame: () => game(), useWorld: <T,>(read: (s: Simulation) => T) => read(h.sim) };
});
vi.mock('@/ui/guide/Guide', async (orig) => {
  const real = await orig<typeof import('@/ui/guide/Guide')>();
  const { createElement: ce } = await import('react');
  const words = (c: unknown): string => (Array.isArray(c) ? c.map(words).join('') : typeof c === 'string' || typeof c === 'number' ? String(c) : '');
  return { ...real, Gated: (props: Parameters<typeof real.Gated>[0]) => { h.clicks.push({ feature: props.feature, label: words(props.children).trim(), onClick: props.onClick as never }); return ce(real.Gated, props); } };
});
const { BankLending } = await import('@/ui/bank/BankLending');
addCountryHolidays('uk', readFileSync('public/holidays/uk.tsv', 'utf8'));
const at = (y: number, m: number, d: number, hr = 9) => instantFromZoned({ year: y, month: m, day: d, hour: hr, minute: 0 }, 'America/New_York');
const onScreen = (html: string) => html.replace(/\stitle="[^"]*"/g, '').replace(/<!-- -->/g, '').replace(/<[^>]+>/g, ' ').replace(/&#x27;/g, '\'').replace(/&amp;/g, '&').replace(/\s+/g, ' ');

it('probe', async () => {
  const config = newLifeFrom({ homeRegionId: 'uk-eng-london', firstName: 'Ada', lastName: 'Cole', pronouns: 'she/her', wealth: 'modest', bankId: 'us-chase', priorResidence: { cityId: 'uk-eng-london', fromYear: 2008, fromMonth: 9 }, homeBankId: 'gb-hsbc' } as Partial<NewSaveConfig>);
  const sim = createSave(1, 'cov-od-hsbc', config);
  await loadPlacesFor(sim.universe);
  const home = Object.values(sim.universe.accounts).find((a) => a.ownerId === sim.player.id && a.bankId === 'gb-hsbc' && a.kind === 'checking')!;
  sim.advanceTo(at(2026, 10, 2, 9));
  const out: string[] = [];
  for (const primary of [false, true]) {
    if (primary) expect(sim.execute({ kind: 'bank.set_primary', payload: { accountId: home.id } }).ok).toBe(true);
    h.sim = sim; h.clicks = [];
    const text = onScreen(renderToStaticMarkup(createElement(BankLending, { bank: bankById('gb-hsbc')!, account: home, show: ['borrowing'] })));
    const i = text.indexOf('Overdraft');
    out.push(`primary=${primary} screen: ${text.slice(Math.max(0, i - 20), i + 700)}`);
    const arrange = h.clicks.filter((c) => c.feature === 'bank.arrange_overdraft');
    out.push(`  arrange drawn: ${JSON.stringify(arrange.map((c) => c.label))}`);
    const r = sim.execute({ kind: 'bank.arrange_overdraft', payload: { limit: 100_00, accountId: home.id } });
    out.push(`  command: ${r.ok ? 'ARRANGED' : r.error}`);
    out.push(`  other gated: ${JSON.stringify(h.clicks.filter((c) => c.feature !== 'bank.arrange_overdraft').map((c) => `${c.feature}:${c.label}`))}`);
    const b = sim.execute({ kind: 'bank.borrow', payload: { amount: 1000_00, months: 12, bankId: 'gb-hsbc' } });
    out.push(`  borrow: ${b.ok ? 'LENT' : b.error}`);
    const lt = text.indexOf('Personal Loan'); out.push(`  loan panel: ${text.slice(lt, lt + 900)}`);
  }
  console.error(out.join('\n'));
}, 600_000);

